/* Service features: fixed price menu, portfolio and profile score, review replies,
   change orders, cancellation policy, materials deposits, business insights */
const MENU_BY_CAT={
 Plumbing:[["Replace a tap cartridge",45,60],["Unblock a sink or drain",60,60],["Fix a running toilet",55,60],["Fit a new shower head",35,30]],
 Electrical:[["Replace a light fitting",50,60],["Add a double socket",75,90],["Fit a smoke alarm",30,30],["Fault finding, first hour",55,60]],
 Painting:[["Paint one wall",90,180],["Fill and paint cracks",60,120],["Paint a door and frame",70,120]],
 Cleaning:[["Two room flat clean",65,150],["End of tenancy clean",160,300],["Oven deep clean",45,90]],
 Handyman:[["Assemble flat pack furniture",40,60],["Hang shelves or pictures",35,60],["Mount a TV on the wall",55,60]],
 Moving:[["Small van, two hours",90,120],["Move a sofa or bed",50,60],["Packing help, one hour",30,60]]};
const PORT_BY_CAT={
 Plumbing:["Kitchen tap replaced","Bathroom drain unblocked","New shower mixer fitted","Radiator valve changed"],
 Electrical:["Ceiling lights rewired","New sockets in a home office","Fuse box upgraded","Garden lighting fitted"],
 Painting:["Living room repainted","Front door refinished","Stairwell walls restored","Bedroom feature wall"],
 Cleaning:["End of tenancy clean","Kitchen deep clean","Office weekly clean","Windows inside and out"],
 Handyman:["Wardrobe assembled","Shelving wall fitted","TV mounted","Door hinges replaced"],
 Moving:["Two room flat moved","Piano moved safely","Student move to Tartu","Office furniture moved"]};
const PORT_TONES=[["#CFE6DC","#8CC7B0"],["#F2E3C4","#E4BE73"],["#E4DED3","#BFB4A2"],["#D8E3EE","#9DB6CF"]];
const CPOL={
 Flexible:{free:24,fee:t=>15,label:"Free until 24 h before. After that a €15 call out fee."},
 Moderate:{free:48,fee:t=>Math.round(t*0.25*100)/100,label:"Free until 48 h before. After that 25% of the job."},
 Strict:{free:72,fee:t=>Math.round(t*0.5*100)/100,label:"Free until 72 h before. After that 50% of the job."}};
const hashId=s=>[...String(s)].reduce((a,c)=>a+c.charCodeAt(0),0);
const catOf=p=>MENU_BY_CAT[p.cat]?p.cat:"Handyman";
function pmenu(p){const f=(p.rate||40)/40;return MENU_BY_CAT[catOf(p)].map(([n,pr,m])=>({name:n,price:Math.max(25,Math.round(pr*f/5)*5),mins:m}))}
function pport(p){const area=["Kesklinn","Kalamaja","Kadriorg","Kristiine","Mustamäe"];return PORT_BY_CAT[catOf(p)].slice(0,3).map((c,i)=>({cap:c,where:area[(hashId(p.id)+i)%area.length],when:["2 weeks ago","last month","in September"][i]}))}
const pcpol=p=>p.name==="Mart Kask"?"Moderate":["Flexible","Moderate","Strict"][hashId(p.id)%3];
const mins=m=>m<60?m+" min":(m%60?(m/60).toFixed(1).replace(".0",""):m/60)+" h";
const tile=(it,i,small)=>`<div class="ptile"><span class="pimg" style="background:linear-gradient(135deg,${PORT_TONES[i%4][0]},${PORT_TONES[i%4][1]})"><span class="ptag">Before and after</span>${ico(["wrench","check","sparkle","home"][i%4],"rgba(22,32,29,.55)",small?22:28)}</span><b>${esc(it.cap)}</b><small>${esc(it.where||"Tallinn")}  ·  ${esc(it.when||"recently")}</small></div>`;

/* provider defaults */
function svcEnsure(){
  const base=MENU_BY_CAT[pTrade()]||MENU_BY_CAT.Handyman;
  if(!S.menu)S.menu=base.slice(0,3).map(([n,p,m])=>({name:n,price:p,mins:m}));
  if(!S.portfolio)S.portfolio=(PORT_BY_CAT[pTrade()]||PORT_BY_CAT.Handyman).slice(0,2).map((c,i)=>({cap:c,where:["Kalamaja","Kesklinn"][i],when:["2 weeks ago","last month"][i]}));
  if(S.bio===undefined)S.bio="Licensed "+(pTrade()||"Plumbing").toLowerCase()+" professional in Tallinn for 11 years. I send a written quote before starting and leave the place tidy.";
  S.cpol=S.cpol||"Moderate";S.revReplies=S.revReplies||{0:{text:"Thank you Sofia, it was a pleasure. Call me any time.",when:"2 weeks ago"}};S.crates=S.crates||{};
}
const SCORE=[["pphoto","Profile photo",15,"Add photo"],["bio","About you",10,"Write"],["portfolio","Three photos of your work",25,"Add photo"],["insurance","Liability insurance certificate",20,"Upload"],["menu","Three or more fixed price services",15,"Add"],["verified","Verified ID and licence",15,"Verify"]];
const scoreDone=k=>k==="portfolio"?S.portfolio.length>=3:k==="menu"?S.menu.length>=3:k==="bio"?!!(S.bio||"").trim():!!S[k];
const pscore=()=>SCORE.reduce((a,[k,,w])=>a+(scoreDone(k)?w:0),0);

const PREVS=[["Sofia R.","Spanish","Fixed the tap in 40 minutes and explained everything through the translation. Very tidy.",5,"2 weeks ago"],["Lukas M.","German","Good work, but he arrived 20 minutes late and did not message.",4,"3 weeks ago"],["Chloé D.","French","Unblocked the drain quickly and the price was exactly the quote.",5,"1 month ago"],["Priya N.","English","Had to come back a second time, but he did it for free the next day.",4,"1 month ago"]];
const RTPL=["Thank you, it was a pleasure to help.","Sorry about the delay, I now message if I am running late.","Thanks for your patience, glad it is fixed now."];

/* expat side blocks, used by expat.js screens */
function exMenuBlock(p){const m=pmenu(p);return `<div class="col" style="gap:10px"><div class="row between" style="align-items:baseline"><b style="font-family:Sora,sans-serif;font-size:17px">Fixed price services</b><span class="muted">Book instantly, no quote</span></div><div class="card" style="padding:2px 14px">${m.map((it,i)=>`<button class="mrow" data-sv="exmenu" data-arg="${i}"><span style="flex:1;min-width:0"><b>${esc(it.name)}</b><small>${mins(it.mins)}  ·  materials quoted separately if needed</small></span><span class="mprice">${money(it.price)}</span><span class="pill ok" style="flex-shrink:0">Book</span></button>`).join("")}</div></div>`}
function exPortBlock(p){return `<div class="col" style="gap:10px"><div class="row between" style="align-items:baseline"><b style="font-family:Sora,sans-serif;font-size:17px">Recent work</b><span class="muted">Photos from Kodu jobs</span></div><div class="pgrid">${pport(p).map((it,i)=>tile(it,i,true)).join("")}</div></div>`}
function exPolicyBlock(p){const k=pcpol(p);return `<div class="card row" style="gap:12px;align-items:flex-start"><span class="eic" style="width:36px;height:36px;border-radius:11px;flex-shrink:0">${ico("calendar","#16201D",18)}</span><span><b style="font-size:15px">${k} cancellation</b><span class="muted" style="display:block">${CPOL[k].label}</span></span></div>`}
const exRevReply=(p,i)=>i===0?`<div class="rreply"><b>Reply from ${esc(p.name.split(" ")[0])}</b><span>Thank you, it was a pleasure to help. Call me any time.</span></div>`:"";
function exCOBlock(j,p){if(!j.co)return "";const f=p.name.split(" ")[0];const fee=Math.round(j.co.amt*0.1*100)/100;
  if(j.co.status==="pending")return `<div class="card col cocard" style="gap:10px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">${esc(f)} asks for extra work</b><span class="pill rev">Needs your OK</span></div><p class="sub" style="font-size:15px">“${esc(j.co.reason)}”</p><div class="row" style="gap:10px;align-items:center"><span class="photo done" style="width:72px;height:72px">${ico("check","#fff",18)}Photo</span><span class="col" style="gap:2px;flex:1"><span class="row between"><span>Extra work</span><b>${money(j.co.amt)}</b></span><span class="row between muted"><span>Kodu fee 10%</span><span>${money(fee)}</span></span><span class="row between" style="color:var(--green);font-weight:700"><span>Added to escrow</span><span>${money(j.co.amt+fee)}</span></span></span></div><div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" data-sv="coapprove">Approve ${money(j.co.amt+fee)}</button><button class="btn s sm" style="flex:1" data-sv="codecline">Decline</button></div><span class="muted">If you decline, ${esc(f)} finishes the original job at the quoted price.</span></div>`;
  return `<div class="note">${ico(j.co.status==="approved"?"check":"flag","#16201D",16)}<span>${j.co.status==="approved"?`You approved ${money(j.co.amt+fee)} of extra work. It is held in escrow with the rest.`:`You declined the extra work. ${esc(f)} finishes the original job only.`}</span></div>`}
const exDepositNote=(j,p)=>j.deposit&&j.materials?`<div class="note">${ico("wrench","#16201D",16)}<span><b>Materials deposit.</b> ${money(j.materials)} goes to ${esc(p.name.split(" ")[0])} when you pay, so the parts can be bought before the visit. The rest stays in escrow until you confirm the job.</span></div>`:"";

/* provider screens */
Object.assign(SCREENS,{
previews:()=>{pensure();svcEnsure();const dist=[[5,112],[4,11],[3,3],[2,1],[1,0]];const done=S.pjobs.filter(j=>j.status==="released");
 return `${bar()}${head("Reviews","Reply in your language. Kodu translates your reply for every reader.")}
<div class="card row" style="gap:18px;align-items:center"><span class="col center" style="align-items:center;gap:2px"><b style="font-family:Sora,sans-serif;font-size:38px;line-height:1">${(S.rating||4.9).toFixed(1)}</b>${stars(5)}<span class="muted" style="font-size:12px">${S.reviews||127} reviews</span></span><span class="col" style="flex:1;gap:5px">${dist.map(([s,n])=>`<span class="row" style="gap:8px;font-size:12px"><span style="width:10px">${s}</span><span class="ibar" style="flex:1"><span style="width:${n/112*100}%"></span></span><span class="muted" style="width:24px;text-align:right">${n}</span></span>`).join("")}</span></div>
${PREVS.map(([n,l,t,r,w],i)=>{const rep=S.revReplies[i];return `<div class="card col" style="gap:8px;padding:14px"><div class="row" style="gap:10px"><span style="width:36px;height:36px;border-radius:18px;background:var(--mint);display:inline-flex;align-items:center;justify-content:center;font-weight:700">${n[0]}</span><span style="flex:1"><b style="font-size:15px">${n}</b> <span class="muted">· wrote in ${l}</span><span class="muted" style="display:block;font-size:12px">${w}</span></span>${stars(r)}</div><p class="sub" style="font-size:14px">${t}</p>
${rep?`<div class="rreply"><b>Your reply  ·  ${esc(rep.when)}</b><span>${esc(rep.text)}</span><button class="link" style="font-size:13px;align-self:flex-start" data-sv="revedit" data-arg="${i}">Edit</button></div>`:S.replyOpen===i?`<form data-form="revreply" class="col" style="gap:8px"><div class="row wrap" style="gap:6px">${RTPL.map(x=>`<button type="button" class="chip" style="height:30px;font-size:12px" data-sv="revtpl" data-arg="${esc(x)}">${esc(x.split(",")[0])}</button>`).join("")}</div><textarea class="ta" name="rtext" placeholder="Write in ${LNAME[pNative()]}">${esc(S.replyDraft||"")}</textarea><div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" type="submit">Post reply</button><button type="button" class="btn s sm" data-sv="revcancel">Cancel</button></div></form>`:`<button class="btn g sm" style="align-self:flex-start" data-sv="revopen" data-arg="${i}">${ico("chat","#16201D",16)}Reply publicly</button>`}</div>`}).join("")}
<div class="col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Rate your customers</b><p class="muted" style="margin-top:-4px">Private. Only Kodu sees these. Customers with repeated low ratings are reviewed by our team.</p><div class="card" style="padding:2px 14px">${done.slice(0,4).map(j=>{const e=ex(j.eid);const v=S.crates[j.id]||0;return `<div class="row" style="gap:10px;padding:10px 0;border-bottom:1px solid #EDE8DF">${exav(e,34)}<span style="flex:1;min-width:0"><b style="font-size:14px">${e.name}</b><span class="muted" style="display:block;font-size:12px">${esc(j.title)}</span></span><span class="row" style="gap:2px">${[1,2,3,4,5].map(s=>`<button class="cstar ${s<=v?"on":""}" data-sv="crate" data-arg="${j.id}:${s}" aria-label="${s} stars">★</button>`).join("")}</span></div>`}).join("")}</div></div>`},

pinsights:()=>{pensure();svcEnsure();const rate=insRate();
 const dem=[["Kesklinn",34],["Kalamaja",27],["Põhja-Tallinn",19],["Kristiine",12],["Mustamäe",8]];const cover=(S.areas||"Kesklinn, Kalamaja").toLowerCase();
 const r=S.pricing==="job"?null:pRate();const lo=30,hi=55,avg=41;const pos=r?Math.max(0,Math.min(100,(r-lo)/(hi-lo)*100)):0;
 const heat=[["Mon",[3,2,2,1]],["Tue",[2,2,3,1]],["Wed",[2,3,2,1]],["Thu",[3,2,2,2]],["Fri",[2,2,3,2]],["Sat",[4,4,3,1]],["Sun",[2,3,2,0]]];
 const top=[["Leaking taps",31],["Blocked drains",24],["Running toilets",18],["Boilers and radiators",12]];
 const hasDrain=S.menu.some(m=>/drain/i.test(m.name));
 return `${bar()}${head("Insights","How your business is doing over the last 30 days.")}
<div class="kgrid">${[[rate+"%","Quotes accepted","+6 points vs September","up"],["12 min","Median reply time","Tallinn average 41 min","up"],["214","Profile views","+18% vs September","up"],["23%","Repeat customers","4 booked you twice","flat"]].map(([v,l,s,k])=>`<div class="card col kpi" style="gap:2px"><b class="kv">${v}</b><span style="font-size:13px;font-weight:600">${l}</span><span class="muted" style="font-size:12px">${k==="up"?"▲ ":""}${s}</span></div>`).join("")}</div>
<div class="card col" style="gap:10px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">Where the demand is</b><span class="muted" style="font-size:12px">${pTrade()} requests</span></div>${dem.map(([a,n])=>`<div class="col" style="gap:4px"><span class="row between" style="font-size:14px"><span>${a}${cover.includes(a.toLowerCase())?` <span class="pill ok" style="margin-left:4px">You cover</span>`:""}</span><b>${n}%</b></span><span class="ibar"><span style="width:${n/34*100}%"></span></span></div>`).join("")}${cover.includes("põhja")?"":`<span class="muted">Põhja-Tallinn is next to Kalamaja and has 19% of requests. Add it to your areas to see them.</span>`}</div>
${r?`<div class="card col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Your price against the area</b><div class="prange"><span class="pband" style="left:0;right:0"></span><span class="pavg" style="left:${(avg-lo)/(hi-lo)*100}%"><small>Average ${money(avg).replace(".00","")}</small></span><span class="pme" style="left:${pos}%"><small>You ${money(r).replace(".00","")}</small></span></div><div class="row between muted" style="font-size:12px"><span>${money(lo).replace(".00","")} per hour</span><span>${money(hi).replace(".00","")} per hour</span></div><span class="sub" style="font-size:14px">${r<avg?`You are ${Math.round((1-r/avg)*100)}% below the Tallinn average for ${pTrade().toLowerCase()}. Providers rated 4.8 and above who charge up to ${money(avg-1).replace(".00","")} keep the same ranking in search.`:`You are above the Tallinn average. Your rating keeps you competitive, but the fixed price menu helps price sensitive customers.`}</span></div>`:""}
<div class="card col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">When customers want you</b><div class="heat"><span></span>${["Morning","Midday","Afternoon","Evening"].map(x=>`<small>${x}</small>`).join("")}${heat.map(([d,v])=>`<small>${d}</small>${v.map(n=>`<span class="h${n}"></span>`).join("")}`).join("")}</div><span class="muted">Saturday mornings get the most requests. ${(S.avail.Sat||[]).length<2?"You have only "+(S.avail.Sat||[]).length+" Saturday slot open.":"You are open then."}</span></div>
<div class="card col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Most requested jobs</b>${top.map(([a,n])=>`<div class="col" style="gap:4px"><span class="row between" style="font-size:14px"><span>${a}</span><b>${n}%</b></span><span class="ibar alt"><span style="width:${n/31*100}%"></span></span></div>`).join("")}</div>
<div class="col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Ways to get more work</b>${[[(S.avail.Sat||[]).length<2,"calendar","Open two more Saturday slots","Saturday mornings are your busiest time.","Open slots","satslots"],[!hasDrain,"wrench","Add “Unblock a sink or drain” to your menu","It is the second most requested job and customers can book it instantly.","Add it","adddrain"],[pscore()<80,"star","Complete your profile","Profiles above 80% get up to 3 times more requests. Yours is at "+pscore()+"%.","Open profile","toprofile"]].filter(x=>x[0]).map(([,i,t,s,b,a])=>`<div class="card row" style="gap:12px;align-items:center"><span class="eic" style="width:40px;height:40px;border-radius:12px;flex-shrink:0">${ico(i,"#16201D",20)}</span><span style="flex:1;min-width:0"><b style="font-size:15px">${t}</b><span class="muted" style="display:block;font-size:13px">${s}</span></span><button class="btn g sm" style="flex-shrink:0" data-sv="${a}">${b}</button></div>`).join("")||`<div class="note">${ico("check","#16201D",16)}<span>You have done everything we would suggest this month. Nice work.</span></div>`}</div>`}
});

function insRate(){const acc=S.pjobs.filter(j=>["paid","done","released","disputed"].includes(j.status)).length,sent=acc+S.pjobs.filter(j=>["quoted","cancelled","declined"].includes(j.status)).length;return Math.round((acc+34)/(sent+50)*100)}
/* provider blocks used inside provider.js screens */
function provScoreBlock(){const sc=pscore();return `<div class="card col" style="gap:10px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">Profile strength</b><b style="font-family:Sora,sans-serif;font-size:22px;color:${sc>=80?"var(--green)":"var(--ink)"}" class="scorev">${sc}%</b></div><div class="bar"><span style="width:${sc}%"></span></div><span class="muted">${sc>=80?"Strong profile. You rank higher in search in your districts.":"Profiles above 80% get up to 3 times more requests."}</span><div class="col" style="gap:0">${SCORE.map(([k,t,w,b])=>{const ok=scoreDone(k);return `<div class="row" style="gap:10px;padding:8px 0;border-top:1px solid #EDE8DF"><span class="sck ${ok?"on":""}">${ok?ico("check","#fff",14):""}</span><span style="flex:1;font-size:14px;${ok?"color:var(--muted)":""}">${t}</span>${ok?`<span class="muted" style="font-size:12px">+${w}%</span>`:`<button class="btn g sm" style="height:32px;padding:0 12px;font-size:13px" data-sv="score" data-arg="${k}">${b}  +${w}%</button>`}</div>`}).join("")}</div></div>`}
function provPortBlock(){return `<div class="col" style="gap:10px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">Your work</b><span class="muted">${S.portfolio.length} photos</span></div><div class="pgrid">${S.portfolio.map((it,i)=>tile(it,i,true)).join("")}<button class="ptile padd" data-sv="portadd"><span class="pimg">${ico("plus","#56605C",26)}</span><b>Add a photo</b><small>Before and after works best</small></button></div></div>`}
function provMenuBlock(){return `<div class="card col" style="gap:8px"><div class="row between"><b>Service menu</b><span class="muted" style="font-size:12px">Customers book these instantly</span></div>${S.menu.map((m,i)=>`<div class="row" style="gap:10px;padding:8px 0;border-top:1px solid #EDE8DF"><span style="flex:1;min-width:0"><b style="font-size:14px;font-weight:600">${esc(m.name)}</b><span class="muted" style="display:block;font-size:12px">${mins(m.mins)}  ·  instant booking</span></span><span class="row" style="gap:4px;align-items:center"><button class="qrx" style="position:static" data-sv="mprice" data-arg="${i}:-5" aria-label="Lower price">−</button><b style="font-family:Sora,sans-serif;min-width:52px;text-align:center">${money(m.price).replace(".00","")}</b><button class="qrx" style="position:static" data-sv="mprice" data-arg="${i}:5" aria-label="Raise price">+</button></span><button class="link" style="font-size:13px;color:var(--muted)" data-sv="mdel" data-arg="${i}">Remove</button></div>`).join("")}
${S.menuAdding?`<form data-form="menuadd" class="col" style="gap:8px;border-top:1px solid #EDE8DF;padding-top:10px"><div class="in"><input name="mname" placeholder="Service name, for example Fit a new toilet seat"></div><div class="row" style="gap:8px"><div class="in" style="flex:1"><input name="mprice" inputmode="decimal" placeholder="Price"><span class="muted">€</span></div><div class="in" style="flex:1"><input name="mmins" inputmode="numeric" placeholder="Minutes" value="60"></div></div><div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" type="submit">Add service</button><button type="button" class="btn s sm" data-sv="madd">Cancel</button></div></form>`:`<button class="btn g sm" data-sv="madd">${ico("plus","#16201D",16)}Add a service</button>`}</div>`}
function provPolicyBlock(){return `<div class="card col" style="gap:8px"><div class="row between"><b>Cancellation policy</b><span class="muted" style="font-size:12px">Shown on your profile</span></div>${Object.entries(CPOL).map(([k,v])=>`<button class="row" style="gap:10px;background:none;border:none;border-top:1px solid #EDE8DF;padding:10px 0;font:inherit;text-align:left;width:100%" data-sv="cpol" data-arg="${k}"><span class="radio ${S.cpol===k?"on":""}"></span><span style="flex:1"><b style="font-size:14px">${k}</b><span class="muted" style="display:block;font-size:13px">${v.label}</span></span></button>`).join("")}<span class="muted" style="font-size:12px">No shows: if nobody lets you in, you keep the full cancellation fee.</span></div>`}
function provCOBlock(j){const e=ex(j.eid),f=e.name.split(" ")[0];
  if(j.co){const fee=Math.round(j.co.amt*0.1*100)/100;return j.co.status==="pending"?`<div class="card col cocard" style="gap:8px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">Change order sent</b><span class="pill rev">Waiting</span></div><span class="sub" style="font-size:14px">“${esc(j.co.reason)}”</span><div class="row between"><span>Extra for you</span><b>${money(j.co.amt)}</b></div><span class="muted">${esc(f)} reads it translated and approves in the app. Do not start the extra work until it is approved.</span></div>`:`<div class="note">${ico(j.co.status==="approved"?"check":"flag","#16201D",16)}<span>${j.co.status==="approved"?`<b>Change order approved.</b> ${money(j.co.amt)} extra is held in escrow with the rest of the job.`:`<b>${esc(f)} declined the change order.</b> Finish the original job at the quoted price.`}</span></div>`}
  if(!S.coOpen)return "";
  return `<div class="card col cocard" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Job bigger than quoted</b><span class="muted">${esc(f)} approves the extra amount in the app before you continue. It is added to escrow, never paid in cash.</span><label class="f"><span class="l">Extra amount for you</span><div class="in ${err.coamt?"err":""}"><input name="coamt" inputmode="decimal" placeholder="35" value="${esc(S.coAmt||"")}"><span class="muted">€</span></div>${err.coamt?`<span class="errt">${err.coamt}</span>`:""}</label><label class="f"><span class="l">What you found (translated to ${LNAME[e.lang]})</span><textarea class="ta" name="coreason" placeholder="Write in ${LNAME[pNative()]}">${esc(S.coReason||"The valve under the sink is corroded and needs replacing too.")}</textarea></label><div class="col" style="gap:6px"><span class="muted" style="font-weight:700">Photo of the problem</span><button type="button" class="photo ${S.coPhoto?"done":""}" data-sv="cophoto">${S.coPhoto?ico("check","#fff",22):ico("plus","#56605C",20)}${S.coPhoto?"Added":"Add photo"}</button>${err.cophoto?`<span class="errt">${err.cophoto}</span>`:""}</div><div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" data-sv="cosend">Send to ${esc(f)}</button><button class="btn s sm" data-sv="cocancel">Cancel</button></div></div>`}
function provInsightTeaser(){return `<button class="card row insteaser" data-go="pinsights"><span class="eic" style="width:40px;height:40px;border-radius:12px;flex-shrink:0">${ico("sparkle","#16201D",20)}</span><span style="flex:1;min-width:0;text-align:left"><b style="font-size:15px">Insights</b><span class="muted" style="display:block;font-size:13px">${insRate()}% of quotes accepted  ·  views up 18%</span></span><span class="muted">${ico("back","#56605C",18).replace("<svg","<svg style=\"transform:rotate(180deg)\"")}</span></button>`}
const cpolFeeFor=(total)=>CPOL[S.cpol||"Moderate"].fee(total);

/* styles */
(()=>{const st=document.createElement("style");st.textContent=`
.mrow{display:flex;align-items:center;gap:10px;width:100%;padding:12px 0;border:none;border-bottom:1px solid #EDE8DF;background:none;font:inherit;text-align:left;cursor:pointer;color:inherit}.mrow:last-child{border-bottom:none}.mrow b{display:block;font-size:15px;font-weight:600}.mrow small{display:block;color:var(--muted);font-size:12px}.mrow .mprice{font-family:Sora,sans-serif;font-weight:700;font-size:16px}
.pgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.ptile{display:flex;flex-direction:column;gap:4px;min-width:0;background:none;border:none;padding:0;font:inherit;text-align:left;color:inherit}.ptile b{font-size:13px;font-weight:600;line-height:1.25}.ptile small{font-size:11px;color:var(--muted)}
.ptile .pimg{position:relative;aspect-ratio:1;border-radius:14px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.ptile .ptag{position:absolute;left:6px;top:6px;font-size:9px;font-weight:700;background:rgba(255,255,255,.85);border-radius:8px;padding:2px 6px;color:#16201D}
.ptile.padd{cursor:pointer}.ptile.padd .pimg{border:1.5px dashed #CFC6B6;background:#fff}
.rreply{display:flex;flex-direction:column;gap:3px;background:#F3EFE7;border-left:3px solid var(--green);border-radius:4px 12px 12px 4px;padding:8px 12px;font-size:14px}.rreply b{font-size:12px;color:var(--green)}
.cstar{border:none;background:none;font-size:20px;color:#D9D2C5;cursor:pointer;padding:0 1px;line-height:1}.cstar.on{color:#E4A72D}
.ibar{display:block;height:8px;border-radius:4px;background:#EDE8DF;overflow:hidden}.ibar>span{display:block;height:100%;background:var(--green);border-radius:4px;animation:ibarIn .9s cubic-bezier(.2,.8,.2,1) both}.ibar.alt>span{background:#E4BE73}
@keyframes ibarIn{from{width:0!important}}
.kgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.kpi{padding:14px}.kpi .kv{font-family:Sora,sans-serif;font-size:26px;letter-spacing:-.02em}
.prange{position:relative;height:56px;margin:4px 8px 0}.prange .pband{position:absolute;top:26px;height:8px;border-radius:4px;background:linear-gradient(90deg,#CFE6DC,#8CC7B0,#E4BE73)}
.prange .pavg,.prange .pme{position:absolute;top:18px;width:2px;height:24px;background:#16201D;transform:translateX(-1px)}.prange .pme{background:var(--green);width:14px;height:14px;border-radius:7px;top:23px;transform:translateX(-7px);border:3px solid #fff;box-shadow:0 0 0 2px var(--green)}
.prange small{position:absolute;white-space:nowrap;font-size:11px;font-weight:700;transform:translateX(-50%);left:50%}.prange .pavg small{top:-18px;color:#56605C}.prange .pme small{top:22px;color:var(--green)}
.heat{display:grid;grid-template-columns:38px repeat(4,minmax(0,1fr));gap:4px;align-items:center}.heat small{font-size:11px;color:var(--muted);text-align:center}.heat small:nth-child(5n+1){text-align:left}.heat>span{height:22px;border-radius:6px;background:#EDE8DF}.heat .h1{background:#DCEFE6}.heat .h2{background:#AFDCC8}.heat .h3{background:#6FBD9B}.heat .h4{background:#0E5A4C}
.sck{width:22px;height:22px;border-radius:11px;border:1.5px solid #CFC6B6;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}.sck.on{background:var(--green);border-color:var(--green)}
.cocard{border:1.5px solid #E4BE73;background:#FFFBF2}
.insteaser{gap:12px;align-items:center;width:100%;font:inherit;color:inherit;cursor:pointer}
@media (min-width:900px){body:not(.phone-mode) .pgrid{grid-template-columns:repeat(4,minmax(0,1fr))}body:not(.phone-mode) .kgrid{grid-template-columns:repeat(4,minmax(0,1fr))}}
`;document.head.appendChild(st)})();

/* events */
document.addEventListener("click",ev=>{const t=ev.target.closest("[data-sv]");if(!t)return;ev.stopPropagation();const a=t.dataset.sv,arg=t.dataset.arg;
  if(a==="exmenu"){const p=find(S.view);const it=pmenu(p)[+arg];S.draft={title:it.name,desc:"Booked from the fixed price menu.",menu:+arg,price:it.price,mins:it.mins};save();go("slots");return}
  if(a==="coapprove"||a==="codecline"){const j=S.jobs2.find(x=>x.id===S.jobId);j.co.status=a==="coapprove"?"approved":"declined";const p=find(j.pid);const c=S.chats[p.id];if(c){c.msgs.push({me:true,text:a==="coapprove"?"Yes, please go ahead with the extra work.":"Please only do the original job for now.",orig:"",when:"now"})}save();render();toast(a==="coapprove"?"Extra work approved and added to escrow":"Extra work declined");return}
  if(a==="ecoarrive"){const j=S.jobs2.find(x=>x.id===S.jobId);j.co={amt:35,reason:"The valve under the sink is corroded and needs replacing too, otherwise it will leak again.",status:"pending"};const p=find(j.pid);const c=S.chats[p.id];if(c)c.msgs.push({sys:true,text:p.name.split(" ")[0]+" sent a change order · waiting for your approval"});save();render();toast(p.name.split(" ")[0]+" asks for extra work");return}
  pensure();svcEnsure();
  if(a==="revopen"){S.replyOpen=+arg;S.replyDraft="";save();render();return}
  if(a==="revedit"){S.replyDraft=S.revReplies[+arg].text;delete S.revReplies[+arg];S.replyOpen=+arg;save();render();return}
  if(a==="revcancel"){S.replyOpen=null;save();render();return}
  if(a==="revtpl"){const ta=document.querySelector("textarea[name=rtext]");if(ta){ta.value=arg;S.replyDraft=arg}return}
  if(a==="crate"){const [id,n]=arg.split(":");S.crates[id]=+n;save();render();toast("Private rating saved");return}
  if(a==="score"){if(arg==="pphoto"){S.pphoto=true;toast("Profile photo added")}else if(arg==="bio"){S.bio=S.bio||"Licensed professional in Tallinn. Written quote before every job.";toast("About you saved")}else if(arg==="portfolio"){addPort()}else if(arg==="insurance"){S.insurance=true;toast("Insurance certificate uploaded, Insured badge added")}else if(arg==="menu"){S.menuAdding=true}else if(arg==="verified"){go("verify");return}save();render();return}
  if(a==="portadd"){addPort();save();render();return}
  if(a==="madd"){S.menuAdding=!S.menuAdding;save();render();return}
  if(a==="mdel"){S.menu.splice(+arg,1);save();render();toast("Removed from your menu");return}
  if(a==="mprice"){const [i,dlt]=arg.split(":").map(Number);S.menu[i].price=Math.max(10,S.menu[i].price+dlt);save();render();return}
  if(a==="cpol"){S.cpol=arg;save();render();toast(arg+" policy is now on your profile");return}
  if(a==="coopen"){S.coOpen=true;S.coPhoto=false;S.coAmt="";err={};save();render();setTimeout(()=>{const c=document.querySelector(".cocard");if(c)c.scrollIntoView({block:"center",behavior:"smooth"})},60);return}
  if(a==="cocancel"){S.coOpen=false;err={};save();render();return}
  if(a==="cophoto"){readCO();S.coPhoto=true;err={};save();render();return}
  if(a==="cosend"){readCO();const v=+String(S.coAmt).replace(",",".");err={};if(!(v>0&&v<=2000))err.coamt="Enter the extra amount";if(!S.coPhoto)err.cophoto="Add a photo so the customer can see the problem";if(Object.keys(err).length){render();return}
    const j=S.pjobs.find(x=>x.id===S.preqId);const e=ex(j.eid);j.co={amt:v,reason:S.coReason||"Extra work needed.",status:"pending"};S.coOpen=false;const c=S.pchats[j.eid];c.msgs.push({me:true,text:`I found more work: ${j.co.reason} Extra ${money(v)}.`,orig:"",when:"now"});c.msgs.push({sys:true,text:"Change order sent · waiting for "+e.name.split(" ")[0]});c.t=Date.now();save();render();toast("Change order sent and translated");
    setTimeout(()=>{if(j.co&&j.co.status==="pending"){j.co.status="approved";c.msgs.push({text:"Okay, please go ahead with the extra work.",orig:"(original)",when:"now"});save();render();toast(e.name.split(" ")[0]+" approved "+money(v)+" extra")}},3200);return}
  if(a==="plate"){const j=S.pjobs.find(x=>x.id===S.preqId);const fee=cpolFeeFor(pq(j).net);j.status="cancelled";j.lateFee=fee;const c=S.pchats[j.eid];c.msgs.push({sys:true,text:ex(j.eid).name.split(" ")[0]+" cancelled 6 h before the visit · "+S.cpol+" policy applied"});save();render();toast("Late cancellation: you keep "+money(fee));return}
  if(a==="pinstant"){const m=S.menu[0];if(!m){toast("Add a service to your menu first","err");return}const e=EXPATS[5%EXPATS.length];const id="i"+Date.now();S.pjobs.unshift({id,eid:e.id,title:m.name,desc:"Booked from your service menu at a fixed price.",photos:1,day:"Thu",slot:"11:00",date:16,status:"paid",fixed:m.price,instant:true,hours:m.mins/60,materials:0,matDesc:"none",ago:"just now",paidAt:"just now"});
    if(!S.pchats[e.id])S.pchats[e.id]={eid:e.id,t:Date.now(),unread:0,msgs:[{sys:true,text:`Chat with ${e.name.split(" ")[0]} started · translated automatically`}]};const c=S.pchats[e.id];c.msgs.push({sys:true,text:`Instant booking: ${m.name}, ${money(m.price)} · paid into escrow`});c.unread=(c.unread||0)+1;c.t=Date.now();save();render();toast("Instant booking from "+e.name.split(" ")[0]+", already paid");return}
  if(a==="satslots"){S.avail.Sat=["09:00","10:00","11:00"];save();render();toast("Saturday 09:00 to 12:00 is open");return}
  if(a==="adddrain"){const it=(MENU_BY_CAT[pTrade()]||MENU_BY_CAT.Plumbing).find(x=>/drain/i.test(x[0]))||["Unblock a sink or drain",60,60];S.menu.push({name:it[0],price:it[1],mins:it[2]});save();render();toast("Added to your service menu");return}
  if(a==="toprofile"){history=[];go("pme");return}
  if(a==="deptog"){const qf=document.querySelector("form[data-form=quote]");const j=S.pjobs.find(x=>x.id===S.preqId);if(qf){["hours","hoursMax","materials","visitFee"].forEach(k=>{if(qf[k])j[k]=+qf[k].value||0});if(qf.matDesc)j.matDesc=qf.matDesc.value;if(qf.note)j.note=qf.note.value}if(!j.materials)j.materials=pMat()[1];j.deposit=!j.deposit;save();render();return}
},true);
function addPort(){const pool=PORT_BY_CAT[pTrade()]||PORT_BY_CAT.Handyman;const cap=pool[S.portfolio.length%pool.length];S.portfolio.push({cap,where:["Kadriorg","Kristiine","Mustamäe"][S.portfolio.length%3],when:"just now"});toast("Photo added to your work")}
function readCO(){const a=document.querySelector("input[name=coamt]"),r=document.querySelector("textarea[name=coreason]");if(a)S.coAmt=a.value;if(r)S.coReason=r.value}
document.addEventListener("submit",ev=>{const f=ev.target;const k=f.dataset.form;if(k!=="revreply"&&k!=="menuadd")return;ev.preventDefault();ev.stopImmediatePropagation();pensure();svcEnsure();
  if(k==="revreply"){const v=f.rtext.value.trim();if(!v){toast("Write a reply first","err");return}S.revReplies[S.replyOpen]={text:v,when:"just now"};S.replyOpen=null;S.replyDraft="";save();render();toast("Reply posted and translated for readers");return}
  if(k==="menuadd"){const n=f.mname.value.trim(),p=+f.mprice.value.replace(",","."),m=+f.mmins.value||60;if(!n||!(p>=10)){toast("Add a name and a price of at least €10","err");return}S.menu.push({name:n,price:p,mins:m});S.menuAdding=false;save();render();toast("Added to your service menu")}
},true);
